draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);

  // Dog 1 (stressed)
  ctx.lineWidth = 3;
  ctx.strokeStyle = 'black';
  ctx.beginPath();
  ctx.arc(W/4, H/2, 20, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/4, H/2 + 20);
  ctx.lineTo(W/4, H/2 + 50);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/4, H/2 + 30);
  ctx.lineTo(W/4 - 15, H/2 + 40);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/4, H/2 + 30);
  ctx.lineTo(W/4 + 15, H/2 + 40);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/4 - 10 + 10 * Math.sin(t), H/2 - 20);
  ctx.lineTo(W/4 - 10 + 10 * Math.sin(t) - 10, H/2 - 10);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/4 + 10 - 10 * Math.sin(t), H/2 - 20);
  ctx.lineTo(W/4 + 10 - 10 * Math.sin(t) + 10, H/2 - 10);
  ctx.stroke();

  // Dog 2 (calming)
  ctx.beginPath();
  ctx.arc(W * 3/4, H/2, 20, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W * 3/4, H/2 + 20);
  ctx.lineTo(W * 3/4, H/2 + 50);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W * 3/4, H/2 + 30);
  ctx.lineTo(W * 3/4 - 15, H/2 + 40);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W * 3/4, H/2 + 30);
  ctx.lineTo(W * 3/4 + 15, H/2 + 40);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W * 3/4 - 10, H/2 - 20);
  ctx.lineTo(W * 3/4 - 10 - 10 * Math.cos(t), H/2 - 10);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W * 3/4 + 10, H/2 - 20);
  ctx.lineTo(W * 3/4 + 10 + 10 * Math.cos(t), H/2 - 10);
  ctx.stroke();

  ctx.restore();
}
